const fs = require('fs');
const puppeteer = require('puppeteer');

const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ML Infrastructure Architecture</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@400;500;600;700&family=Fragment+Mono:wght@400&display=swap" rel="stylesheet">
<style>
  :root {
    --font-body: 'Bricolage Grotesque', system-ui, sans-serif;
    --font-mono: 'Fragment Mono', 'SF Mono', Consolas, monospace;

    /* Forced Dark Theme */
    --bg: #0f172a;
    --surface: #1e293b;
    --border: rgba(255, 255, 255, 0.1);
    --text: #f8fafc;
    --text-dim: #94a3b8;

    --primary: #38bdf8;
    --primary-dim: rgba(56, 189, 248, 0.14);
    --secondary: #4ade80;
    --tertiary: #fb923c;
    --danger: #f87171;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background-color: var(--bg);
    background-image: radial-gradient(circle, var(--border) 1px, transparent 1px);
    background-size: 24px 24px;
    color: var(--text);
    font-family: var(--font-body);
    padding: 40px;
    height: 100vh;
    display: flex;
    flex-direction: column;
  }

  .header {
    margin-bottom: 20px;
  }

  h1 {
    font-size: 32px;
    font-weight: 700;
    margin-bottom: 6px;
  }

  .subtitle {
    color: var(--text-dim);
    font-family: var(--font-mono);
    font-size: 14px;
    margin-bottom: 12px;
  }

  .mermaid-wrap {
    flex: 1;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    overflow: hidden;
  }

  .mermaid-viewport {
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  /* Legend */
  .legend {
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    margin-top: 20px;
    background: var(--surface);
    padding: 16px;
    border-radius: 8px;
    border: 1px solid var(--border);
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--text);
  }

  .legend-swatch {
    width: 14px;
    height: 14px;
    border-radius: 3px;
  }

  /* Node labels */
  .mermaid .nodeLabel {
    font-family: var(--font-body) !important;
  }

  .mermaid .edgeLabel {
    font-family: var(--font-mono) !important;
    font-size: 12px !important;
    color: var(--text-dim) !important;
    background-color: var(--surface) !important;
  }
</style>
</head>
<body>

<div class="header">
  <h1>ML Infrastructure Architecture Pipeline</h1>
  <p class="subtitle">End-to-End Data, Training, and Inference Flow</p>
</div>

<div class="mermaid-wrap" id="capture-area">
  <div class="mermaid-viewport">
    <div class="mermaid" id="diagram">
graph TD
  %% Nodes
  data_platform["Data Platform<br/>(Spark / Flink)"]:::dataLayer
  feature_store["Feature Store"]:::dataLayer
  training_cluster["Training Cluster<br/>(GPU)"]:::computeLayer
  model_registry["Model Registry"]:::computeLayer
  inference_online["Inference Service<br/>(Online / Real-time)"]:::servingLayer
  inference_offline["Inference Service<br/>(Offline / Batch)"]:::servingLayer
  ab_experiment["A/B Experiment<br/>Platform"]:::servingLayer
  monitoring["Monitoring &<br/>Alerting"]:::observabilityLayer
  version_control["Version Control<br/>& Data Lineage"]:::observabilityLayer

  %% Edges
  data_platform -->|"Raw → Features<br/>12.5 gbps"| feature_store
  feature_store -->|"Training Data<br/>8.0 gbps"| training_cluster
  training_cluster -->|"Trained Models<br/>2.5 gbps"| model_registry
  model_registry -->|"Model Deploy (Online)<br/>1.8 gbps"| inference_online
  model_registry -->|"Model Deploy (Batch)<br/>3.2 gbps"| inference_offline
  inference_online -->|"Predictions (RT)<br/>5.0 gbps"| ab_experiment
  inference_offline -->|"Predictions (Batch)<br/>4.0 gbps"| ab_experiment
  ab_experiment -->|"Metrics & Results<br/>2.0 gbps"| monitoring
  monitoring -->|"Data Quality Alerts"| data_platform
  monitoring -->|"Retrain Trigger"| training_cluster
  version_control -.->|"Feature Versioning"| feature_store
  version_control -.->|"Experiment Tracking"| training_cluster
  version_control -.->|"Model Lineage"| model_registry
  data_platform -.->|"Data Lineage"| version_control
  feature_store -->|"Online Features<br/>6.0 gbps"| inference_online

  %% Classes
  classDef dataLayer fill:#0c4a6e,stroke:#38bdf8,stroke-width:2px,color:#e0f2fe
  classDef computeLayer fill:#14532d,stroke:#4ade80,stroke-width:2px,color:#dcfce7
  classDef servingLayer fill:#7c2d12,stroke:#fb923c,stroke-width:2px,color:#ffedd5
  classDef observabilityLayer fill:#7f1d1d,stroke:#f87171,stroke-width:2px,color:#fee2e2

  %% Node Size by Criticality (7-10)
  style data_platform font-size:20px
  style feature_store font-size:18px
  style training_cluster font-size:22px
  style model_registry font-size:18px
  style inference_online font-size:20px
  style inference_offline font-size:14px
  style ab_experiment font-size:18px
  style monitoring font-size:20px
  style version_control font-size:14px

  %% Edge Thickness by Throughput
  linkStyle 0 stroke-width:6.0px,stroke:#94a3b8
  linkStyle 1 stroke-width:4.5px,stroke:#94a3b8
  linkStyle 2 stroke-width:2.2px,stroke:#94a3b8
  linkStyle 3 stroke-width:1.9px,stroke:#94a3b8
  linkStyle 4 stroke-width:2.6px,stroke:#94a3b8
  linkStyle 5 stroke-width:3.5px,stroke:#94a3b8
  linkStyle 6 stroke-width:3.0px,stroke:#94a3b8
  linkStyle 7 stroke-width:2.0px,stroke:#94a3b8
  linkStyle 8 stroke-width:1.5px,stroke:#fbbf24
  linkStyle 9 stroke-width:1.5px,stroke:#fbbf24
  linkStyle 10 stroke-width:1.5px,stroke:#64748b
  linkStyle 11 stroke-width:1.5px,stroke:#64748b
  linkStyle 12 stroke-width:1.5px,stroke:#64748b
  linkStyle 13 stroke-width:1.5px,stroke:#64748b
  linkStyle 14 stroke-width:4.0px,stroke:#94a3b8
    </div>
  </div>
</div>

<div class="legend">
  <div class="legend-item"><div class="legend-swatch" style="background:#0c4a6e; border: 1px solid #38bdf8"></div> Data Layer</div>
  <div class="legend-item"><div class="legend-swatch" style="background:#14532d; border: 1px solid #4ade80"></div> Compute Layer</div>
  <div class="legend-item"><div class="legend-swatch" style="background:#7c2d12; border: 1px solid #fb923c"></div> Serving Layer</div>
  <div class="legend-item"><div class="legend-swatch" style="background:#7f1d1d; border: 1px solid #f87171"></div> Observability Layer</div>
  <div class="legend-item"><div style="width: 20px; height: 3px; background: #94a3b8;"></div> Primary Flow</div>
  <div class="legend-item"><div style="width: 20px; height: 3px; background: #fbbf24;"></div> Feedback Loop</div>
  <div class="legend-item"><div style="width: 20px; height: 2px; border-bottom: 2px dashed #64748b;"></div> Lineage / Control</div>
</div>

<script type="module">
  import mermaid from 'https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.esm.min.mjs';
  // Use elk layout for better graph structuring
  import elkLayouts from 'https://cdn.jsdelivr.net/npm/@mermaid-js/layout-elk@0.1.4/dist/mermaid-layout-elk.esm.min.mjs';

  mermaid.registerLayoutLoaders(elkLayouts);
  mermaid.initialize({
    startOnLoad: true,
    theme: 'base',
    layout: 'elk',
    themeVariables: {
      fontFamily: "'Bricolage Grotesque', system-ui, sans-serif",
      primaryTextColor: '#f8fafc',
      lineColor: '#94a3b8',
      textColor: '#f8fafc',
    }
  });
</script>

</body>
</html>
`;

fs.writeFileSync('/tmp/diagram.html', htmlContent);

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--font-render-hinting=none'],
    defaultViewport: { width: 1400, height: 1000 }
  });
  const page = await browser.newPage();

  // Expose function to check if mermaid is done
  await page.goto('file:///tmp/diagram.html', { waitUntil: 'networkidle0' });

  // Wait for SVG to appear and be fully rendered
  await page.waitForSelector('.mermaid svg');

  // Small wait for fonts to ensure they render
  await new Promise(r => setTimeout(r, 2000));

  // Capture full page
  await page.screenshot({ path: '/app/output/result.png', fullPage: true });

  await browser.close();
  console.log('Screenshot saved to /app/output/result.png');
})();

